WITH transactions_by_account AS (SELECT account_id, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(txn_type))) AS txn_type_values, MIN(amount) AS min_amount FROM transactions WHERE merchant = 'Shell' GROUP BY account_id) SELECT a.customer_id, a.account_type, tba.txn_type_values, tba.min_amount FROM accounts a LEFT JOIN transactions_by_account tba ON a.id = tba.account_id WHERE tba.min_amount >= 2300 ORDER BY customer_id DESC, txn_type_values DESC;
